def series_F(a,b,x,rtol=1e-12):
    k=0
    term = x/(1*sc.gamma(a*0+b))  # first term k=0 where (k+1)!=1!
    S=term
    while True:
        k+=1
        term *= x/(k+1)  # because multiply by x^(1) / (k+1)  originally? Wait formula: term_k = x^{k+1}/((k+1)! Gamma(ak + b)). For next k, ratio: term_{k}/term_{k-1} = x/(k+1) * Gamma(a*(k-1)+b)/Gamma(ak + b).
        term *= sc.gamma(a*(k-1)+b)/sc.gamma(a*k + b)
        S_new = S + term
        if abs(term) < rtol*abs(S_new):
